CREATE TABLE IF NOT EXISTS users (id INT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(100) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, admin BOOLEAN NOT NULL DEFAULT FALSE, active BOOLEAN NOT NULL DEFAULT TRUE, default_view VARCHAR(30) NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash CHAR(64) PRIMARY KEY, user_id INT NOT NULL, expires_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS clients (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(200) NOT NULL, email VARCHAR(254) NOT NULL DEFAULT '', phone VARCHAR(100) NOT NULL DEFAULT '', address TEXT NOT NULL, notes TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sequences (period CHAR(6) PRIMARY KEY, value INT NOT NULL);
CREATE TABLE IF NOT EXISTS cases (id INT PRIMARY KEY AUTO_INCREMENT, client_id INT NOT NULL, parent_id INT NULL, number VARCHAR(100) NOT NULL UNIQUE, sub_number INT NOT NULL DEFAULT 0, title VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(parent_id,sub_number), FOREIGN KEY(client_id) REFERENCES clients(id), FOREIGN KEY(parent_id) REFERENCES cases(id));
CREATE TABLE IF NOT EXISTS roles (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS user_roles (user_id INT NOT NULL, role_id INT NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS acl (id INT PRIMARY KEY AUTO_INCREMENT, role_id INT NOT NULL, case_id INT NULL, permission VARCHAR(50) NOT NULL, effect VARCHAR(5) NOT NULL, FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE, FOREIGN KEY(case_id) REFERENCES cases(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS folders (id INT PRIMARY KEY AUTO_INCREMENT, case_id INT NOT NULL, path VARCHAR(500) NOT NULL, UNIQUE(case_id,path), FOREIGN KEY(case_id) REFERENCES cases(id));
CREATE TABLE IF NOT EXISTS documents (id INT PRIMARY KEY AUTO_INCREMENT, case_id INT NOT NULL, folder_id INT NOT NULL, title VARCHAR(255) NOT NULL, tags TEXT NOT NULL, FOREIGN KEY(case_id) REFERENCES cases(id), FOREIGN KEY(folder_id) REFERENCES folders(id));
CREATE TABLE IF NOT EXISTS versions (id INT PRIMARY KEY AUTO_INCREMENT, document_id INT NOT NULL, version INT NOT NULL, filename VARCHAR(255) NOT NULL, storage_key VARCHAR(700) NOT NULL UNIQUE, size BIGINT NOT NULL, sha256 CHAR(64) NOT NULL, created_by INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(document_id,version), FOREIGN KEY(document_id) REFERENCES documents(id), FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS metadata_fields (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL UNIQUE, label VARCHAR(200) NOT NULL, type VARCHAR(20) NOT NULL, required BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS metadata_values (case_id INT NOT NULL, field_id INT NOT NULL, value TEXT NOT NULL, PRIMARY KEY(case_id,field_id), FOREIGN KEY(case_id) REFERENCES cases(id), FOREIGN KEY(field_id) REFERENCES metadata_fields(id));
CREATE TABLE IF NOT EXISTS templates (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(200) NOT NULL, subject VARCHAR(255) NOT NULL, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS emails (id INT PRIMARY KEY AUTO_INCREMENT, case_id INT NOT NULL, direction VARCHAR(10) NOT NULL, subject TEXT NOT NULL, sender TEXT NOT NULL, recipients TEXT NOT NULL, body LONGTEXT NOT NULL, source_hash CHAR(64) NULL, original_key VARCHAR(700) NULL, status VARCHAR(20) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(case_id,source_hash), FOREIGN KEY(case_id) REFERENCES cases(id));
CREATE TABLE IF NOT EXISTS settings (name VARCHAR(100) PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, action VARCHAR(100) NOT NULL, entity VARCHAR(100) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
INSERT IGNORE INTO settings VALUES ('default_view','manager'),('number_width','4');
